    /// <summary>
    /// Flat bodies nested in a flat class (#355 step C): a sealed flat class, a flat class that is not sealed (a
    /// subtype in it leaves the element), a flat struct and a version-tolerant one, each the nested type's chain as one
    /// item.
    /// </summary>
    [NinoType]
    public sealed class FlatOuter
    {
        public int Id;
        public FlatLeaf Leaf;
        public string Name;
        public FlatPoint Point { get; set; }
        public FlatOne One;
        public FlatTolerantPoint Tolerant;
    }

    /// <summary><see cref="FlatOuter"/> with a callback: not flat, the same bytes.</summary>
    [NinoType]
    public sealed class FlatOuterTwin
    {
        [NinoOnSerializing]
        internal void Writing() { }

        public int Id;
        public FlatLeaf Leaf;
        public string Name;
        public FlatPointTwin Point { get; set; }
        public FlatOne One;
        public FlatTolerantPointTwin Tolerant;
    }

    /// <summary>A flat struct nesting a flat class (#355 step C): a reference in it, its runs in place.</summary>
    [NinoType]
    public struct FlatWrap
    {
        public FlatMany Many;
        public int X;
    }

    /// <summary><see cref="FlatWrap"/> with a callback: not flat, the same bytes.</summary>
    [NinoType]
    public struct FlatWrapTwin
    {
        [NinoOnSerializing]
        internal void Writing() { }

        public FlatManyProps Many;
        public int X;
    }

    /// <summary>
    /// A chain of nodes each holding a run of <see cref="FlatOuter"/> (nested class bodies): a run whose nested bodies
    /// would open past NinoDepth.Inline goes element by element (#355 step C).
    /// </summary>
    [NinoType]
    public sealed class FlatOuterNode
    {
        public FlatOuter[] Items;
        public FlatOuterNode Next;
    }

    /// <summary><see cref="FlatOuterNode"/> over <see cref="FlatOuterTwin"/>: the same bytes through generated bodies.</summary>
    [NinoType]
    public sealed class FlatOuterNodeTwin
    {
        public FlatOuterTwin[] Items;
        public FlatOuterNodeTwin Next;
    }

    /// <summary>A raw struct with padding (a byte, then an int): never in a block, its own item, padding cleared.</summary>
    public struct FlatPadded
    {
        public byte A;
        public int B;
    }

    /// <summary>
    /// A flat class whose blocks hold bools, raw structs and NinoNullable members (#444), declared so that CoreCLR lays
    /// them out as the wire does: the primitives by size (8, 4, 2, 1), then the structs in declaration order. Its
    /// blocks: Stamp to Count (40 bytes, two bools in it), Big to Price (48 bytes); Name and Padded (a struct with
    /// padding) are items of their own.
    /// </summary>
    [NinoType]
    public sealed class FlatBlocks
    {
        public long Stamp;
        public int Id;
        public short Level;
        public bool Flag;
        public bool Done;
        public DateTime At;
        public NinoNullable<int> Count;
        public string Name;
        public NinoNullable<long> Big;
        public Guid Key;
        public decimal Price;
        public FlatPadded Padded;
    }

    /// <summary><see cref="FlatBlocks"/> with a callback: not flat, the same bytes.</summary>
    [NinoType]
    public sealed class FlatBlocksTwin
    {
        [NinoOnSerializing]
        internal void Writing() { }

        public long Stamp;
        public int Id;
        public short Level;
        public bool Flag;
        public bool Done;
        public DateTime At;
        public NinoNullable<int> Count;
        public string Name;
        public NinoNullable<long> Big;
        public Guid Key;
        public decimal Price;
        public FlatPadded Padded;
    }

    /// <summary>A flat class whose one block ends with two bools (#444): Id, A and B, then a string.</summary>
    [NinoType]
    public class FlatFlags
    {
        public int Id;
        public bool A;
        public bool B;
        public string Name;
    }

    /// <summary><see cref="FlatFlags"/> with a callback: not flat, the same bytes (its type id differs).</summary>
    [NinoType]
    public class FlatFlagsTwin
    {
        [NinoOnSerializing]
        internal void Writing() { }

        public int Id;
        public bool A;
        public bool B;
